// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address actor) public {
        vm.assume(role != 0x00); // DEFAULT_ADMIN_ROLE controls granting; keep rule clean and wide over the rest
        vm.prank(actor);
        c.renounceRole(role, actor);
        // General rule: renouncing a role can never leave (or make) the account hold that role.
        assertTrue(!c.hasRole(role, actor));
    }
}
